import type { ComponentProps } from "react"
import { FormBuilderCombobox } from "@/components/form-builder/FormBuilderCombobox"
import { ChoiceRadioGroup } from "./ChoiceRadioGroup"

type ComboboxProps = ComponentProps<typeof FormBuilderCombobox>
type Props = Omit<ComboboxProps, "options" | "groups"> & {
  options: NonNullable<ComboboxProps["options"]>
}

/** Component settings use radios for up to three choices, searchable lists above that. */
export function SettingsChoice(props: Props) {
  const options = props.emptyLabel
    ? [{ value: "", label: props.emptyLabel }, ...props.options]
    : props.options
  if (options.length === 0 || options.length > 3) return <FormBuilderCombobox {...props} />
  return <ChoiceRadioGroup {...props} options={options} />
}
