import { useId, type ReactNode } from "react"
import { RadioGroup as RadioGroupPrimitive } from "radix-ui"
import { Button } from "@/components/ui/button"
import { RadioGroup } from "@/components/ui/radio-group"
import { cn } from "@/lib/utils"

type Props = {
  value: string
  onValueChange: (value: string) => void
  options: { value: string; label: ReactNode; help?: ReactNode; disabled?: boolean }[]
  disabled?: boolean
  className?: string
  id?: string
  "aria-label"?: string
  title?: string
  "data-testid"?: string
}

/** Shadcn button segments with radio semantics, including exact empty values. */
export function ChoiceRadioGroup({ options, value, onValueChange, disabled, className, id, ...props }: Props) {
  const generatedId = useId()
  const prefix = id ?? generatedId
  return (
    <RadioGroup {...props} id={id} value={value} disabled={disabled} orientation="horizontal"
      data-presentation="buttons"
      className={cn("flex w-fit max-w-full min-w-0 flex-wrap gap-0.5 rounded-md bg-muted p-0.5", className)}
      onValueChange={(next) => {
        if (!disabled && options.some((option) => option.value === next && !option.disabled)) onValueChange(next)
      }}>
      {options.map((option, index) => (
        <div key={option.value} className="grid max-w-full min-w-0 content-start gap-1.5">
          <RadioGroupPrimitive.Item asChild id={`${prefix}-option-${index}`} value={option.value}
            data-option-value={option.value} disabled={disabled || option.disabled}>
            <Button type="button" variant="ghost" size="xs"
              className="h-auto min-h-6 min-w-0 shrink whitespace-normal break-words px-2 py-1 text-muted-foreground aria-[checked=true]:bg-background aria-[checked=true]:text-foreground aria-[checked=true]:shadow-xs">
              {option.label}
            </Button>
          </RadioGroupPrimitive.Item>
          {option.help}
        </div>
      ))}
    </RadioGroup>
  )
}
