import { useMemo, useRef, useState } from "react"
import { Check, ChevronsUpDown } from "lucide-react"
import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"

export type FormBuilderComboboxOption = {
  value: string
  label: string
  disabled?: boolean
}

export type FormBuilderComboboxGroup = {
  label: string
  options: FormBuilderComboboxOption[]
}

type SingleProps = {
  value: string
  onValueChange: (value: string) => void
  options?: FormBuilderComboboxOption[]
  groups?: FormBuilderComboboxGroup[]
  emptyLabel?: string
  placeholder?: string
  searchPlaceholder?: string
  disabled?: boolean
  className?: string
  id?: string
  "aria-label"?: string
  title?: string
  "data-testid"?: string
}
function allOptions(
  options: FormBuilderComboboxOption[],
  groups: FormBuilderComboboxGroup[],
): FormBuilderComboboxOption[] {
  return groups.length ? groups.flatMap((group) => group.options) : options
}

function optionLabel(
  value: string,
  options: FormBuilderComboboxOption[],
  groups: FormBuilderComboboxGroup[],
  emptyLabel?: string,
): string {
  if (!value && emptyLabel) return emptyLabel
  return allOptions(options, groups).find((option) => option.value === value)?.label ?? value
}

function OptionRows({
  options,
  selected,
  onSelect,
}: {
  options: FormBuilderComboboxOption[]
  selected: Set<string>
  onSelect: (value: string) => void
}) {
  return options.map((option) => (
    <CommandItem
      key={option.value}
      value={option.label + " " + option.value}
      data-option-value={option.value}
      disabled={option.disabled}
      onSelect={() => onSelect(option.value)}
    >
      <Check className={cn("size-4", selected.has(option.value) ? "opacity-100" : "opacity-0")} />
      <span className="truncate">{option.label}</span>
    </CommandItem>
  ))
}
export function FormBuilderCombobox({
  value,
  onValueChange,
  options = [],
  groups = [],
  emptyLabel,
  placeholder = "Select...",
  searchPlaceholder = "Search...",
  disabled,
  className,
  ...triggerProps
}: SingleProps) {
  const [open, setOpen] = useState(false)
  const searchInputRef = useRef<HTMLInputElement>(null)
  const selected = useMemo(() => new Set(value ? [value] : []), [value])
  const label = optionLabel(value, options, groups, emptyLabel)

  const choose = (next: string) => {
    if (disabled) return
    onValueChange(next)
    setOpen(false)
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          {...triggerProps}
          type="button"
          variant="outline"
          role="combobox"
          aria-expanded={open}
          disabled={disabled}
          className={cn("w-full justify-between font-normal", className)}
        >
          <span className={cn("truncate", !label && "text-muted-foreground")}>
            {label || placeholder}
          </span>
          <ChevronsUpDown className="ml-2 size-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-[var(--radix-popover-trigger-width)] p-0"
        onOpenAutoFocus={(event) => {
          event.preventDefault()
          searchInputRef.current?.focus()
        }}
      >
        <Command>
          <CommandInput ref={searchInputRef} placeholder={searchPlaceholder} />
          <CommandList>
            <CommandEmpty>No results.</CommandEmpty>
            {emptyLabel ? (
              <CommandGroup>
                <CommandItem data-option-value="" value={emptyLabel} onSelect={() => choose("")}>
                  <Check className={cn("size-4", value === "" ? "opacity-100" : "opacity-0")} />
                  <span className="truncate">{emptyLabel}</span>
                </CommandItem>
              </CommandGroup>
            ) : null}
            {groups.length ? (
              groups.map((group) => (
                <CommandGroup key={group.label} heading={group.label}>
                  <OptionRows options={group.options} selected={selected} onSelect={choose} />
                </CommandGroup>
              ))
            ) : (
              <CommandGroup>
                <OptionRows options={options} selected={selected} onSelect={choose} />
              </CommandGroup>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

type MultiProps = {
  values: string[]
  onValuesChange: (values: string[]) => void
  options: FormBuilderComboboxOption[]
  placeholder?: string
  searchPlaceholder?: string
  disabled?: boolean
  className?: string
  id?: string
  "aria-label"?: string
  title?: string
  "data-testid"?: string
}
export function FormBuilderMultiCombobox({
  values,
  onValuesChange,
  options,
  placeholder = "Select...",
  searchPlaceholder = "Search...",
  disabled,
  className,
  ...triggerProps
}: MultiProps) {
  const [open, setOpen] = useState(false)
  const searchInputRef = useRef<HTMLInputElement>(null)
  const selected = useMemo(() => new Set(values), [values])
  const selectedLabels = options
    .filter((option) => selected.has(option.value))
    .map((option) => option.label)

  const toggle = (value: string) => {
    if (disabled) return
    const next = new Set(selected)
    if (next.has(value)) next.delete(value)
    else next.add(value)
    onValuesChange(options.map((option) => option.value).filter((option) => next.has(option)))
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          {...triggerProps}
          type="button"
          variant="outline"
          role="combobox"
          aria-expanded={open}
          disabled={disabled}
          className={cn("w-full justify-between font-normal", className)}
        >
          <span className={cn("truncate", !selectedLabels.length && "text-muted-foreground")}>
            {selectedLabels.length ? selectedLabels.join(", ") : placeholder}
          </span>
          <ChevronsUpDown className="ml-2 size-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-[var(--radix-popover-trigger-width)] p-0"
        onOpenAutoFocus={(event) => {
          event.preventDefault()
          searchInputRef.current?.focus()
        }}
      >
        <Command>
          <CommandInput ref={searchInputRef} placeholder={searchPlaceholder} />
          <CommandList>
            <CommandEmpty>No results.</CommandEmpty>
            <CommandGroup>
              <OptionRows options={options} selected={selected} onSelect={toggle} />
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}
