import type { MonacoCodeEditorProps } from "../../../../paid/features/code_editor/admin/MonacoCodeEditor"
export function MonacoCodeEditor(props: MonacoCodeEditorProps) {
  const definition = window.MapSVG?.extensions?.get<{ Editor: (props: MonacoCodeEditorProps) => import("react").ReactNode }>("admin.panel", "code-editor")
  return definition ? <definition.Editor {...props} /> : null
}
